create extension if not exists pgcrypto;
create table restaurants(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_at timestamptz not null default now());
create table users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,created_at timestamptz not null default now());
create table restaurant_members(user_id uuid references users(id) on delete cascade,restaurant_id uuid references restaurants(id) on delete cascade,role text not null check(role in ('owner','manager','kitchen','staff')),primary key(user_id,restaurant_id));
create table restaurant_tables(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,label text not null,public_token text unique not null default encode(gen_random_bytes(24),'hex'),active boolean not null default true,created_at timestamptz not null default now(),unique(restaurant_id,label));
create table menu_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,category text not null,name_en text not null,name_kn text,description_en text,description_kn text,price numeric(10,2) not null check(price>=0),image_url text,is_available boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table customer_sessions(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,table_id uuid not null references restaurant_tables(id) on delete cascade,session_token text unique not null default encode(gen_random_bytes(32),'hex'),customer_name text check(customer_name is null or char_length(customer_name) between 2 and 60),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '12 hours'));
create table orders(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,table_id uuid not null references restaurant_tables(id) on delete cascade,session_id uuid not null references customer_sessions(id) on delete cascade,status text not null default 'received' check(status in ('received','accepted','preparing','ready','served','cancelled')),total numeric(10,2) not null check(total>=0),created_at timestamptz not null default now());
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,menu_item_id uuid not null references menu_items(id),name_snapshot text not null,price_snapshot numeric(10,2) not null,quantity integer not null check(quantity>0));
create table service_requests(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references restaurants(id) on delete cascade,table_id uuid not null references restaurant_tables(id) on delete cascade,session_id uuid not null references customer_sessions(id) on delete cascade,type text not null check(type in ('waiter','water','bill')),status text not null default 'open' check(status in ('open','resolved')),created_at timestamptz not null default now());
create index idx_tables_restaurant on restaurant_tables(restaurant_id);create index idx_menu_restaurant on menu_items(restaurant_id);create index idx_orders_restaurant_created on orders(restaurant_id,created_at desc);create index idx_sessions_token on customer_sessions(session_token);
